python3 - <<'PY'
p='/mnt/data/work/dottie-hill-runtime/src/dottie_hill/static/console.js'
s=open(p).read()
s=s.replace("""people.forEach(p=>{const option=node('option','',p.display_name);option.value=p.intelligence_id;$('recipient').append(option);const opt=node('option','',p.display_name);opt.value=p.intelligence_id;$('model-target').append(opt);}); $('auth').hidden=true;""", """people.forEach(p=>{const option=node('option','',p.display_name);option.value=p.intelligence_id;$('recipient').append(option);const opt=node('option','',p.display_name);opt.value=p.intelligence_id;$('model-target').append(opt);if(p.intelligence_id.startsWith('aegis-')){for(const target of ['member-one','member-two']){const option=node('option','',p.display_name);option.value=p.intelligence_id;$(target).append(option);}}});$('member-one').value='aegis-dugan';$('member-two').value='aegis-morita'; $('auth').hidden=true;""")
needle="""  $('mission-form').addEventListener('submit',async event=>{
"""
add="""  $('collaboration-form').addEventListener('submit',async event=>{
    event.preventDefault();const intent=$('intent').value.trim();
    if(!intent){showToast('Enter the intention in the main composer first.');$('intent').focus();return;}
    const first=$('member-one').value, second=$('member-two').value;
    if(!first||!second||first===second){showToast('Choose two different Aegis reviewers.');return;}
    const button=$('collaborate');button.disabled=true;button.textContent='Dispatching independent review…';
    try{
      const c=await call('/v1/collaborations','POST',{intent,participants:[first,second],idempotency_key:crypto.randomUUID()});
      const final=await call(`/v1/collaborations/${c.collaboration_id}/run`,'POST');
      $('response').hidden=false;$('response-title').textContent=`Independent review: ${final.status}`;
      $('response-body').textContent=final.status==='DONE'?`Dottie synthesis completed; see the mission and evidence ledgers for attributed findings.`:`Review ${final.status}: one or more independent branches are unfinished or blocked; no consensus is claimed.`;
      $('response-provenance').textContent=`COLLABORATION: ${final.collaboration_id} · PARTICIPANTS: ${final.participants.join(', ')} · MISSION RECEIPTS: ${final.mission_ids.join(', ')}`;
      showToast(`Independent review ${final.status}.`);await refresh();
    }catch(err){showToast('Review not confirmed: '+short(err.message,160));await refresh();}
    finally{button.disabled=false;button.textContent='Request independent review';}
  });
"""
assert needle in s
s=s.replace(needle,add+needle)
open(p,'w').write(s)
PY
